// Differential harness: run the same argv through the Python executable and the
// Node port, compare stdout / stderr / exit status byte-for-byte.
//
// Cases are passed as a JSON file containing an array of argv arrays, e.g.
//   [["--a", "helloWorld"], ["--a="], []]
// Using spawn with an explicit argv array (no shell) means control characters,
// quotes and newlines reach both programs untouched.
//
//   node diff.mjs cases.json
//
// Prints one line per mismatch plus a summary; exits 1 if anything differed.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const PY = '/workspace/dataset/test17_executable';
const JS = '/output/test17.mjs';

function run(command, argv) {
  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, COLUMNS: '80' },
  });
  return {
    status: result.status,
    stdout: result.stdout ?? Buffer.alloc(0),
    stderr: result.stderr ?? Buffer.alloc(0),
  };
}

function show(argv) {
  return JSON.stringify(argv);
}

function preview(buffer) {
  const text = buffer.toString('utf8');
  return JSON.stringify(text.length > 400 ? `${text.slice(0, 400)}...` : text);
}

const casesPath = process.argv[2];
if (!casesPath) {
  console.error('usage: node diff.mjs <cases.json>');
  process.exit(64);
}

const cases = JSON.parse(readFileSync(casesPath, 'utf8'));
if (!Array.isArray(cases)) {
  console.error('cases file must contain an array of argv arrays');
  process.exit(64);
}

let failures = 0;
for (const argv of cases) {
  const expected = run([PY], argv);
  const actual = run(['node', JS], argv);

  // The program name legitimately differs (argparse uses basename(argv[0]), so
  // the executable says "test17_executable" where the script says "test17.mjs").
  // Usage and error lines are compared with that one token normalised away.
  const normalise = (buffer, prog) => buffer.toString('utf8').split(prog).join('<PROG>');

  const problems = [];
  if (expected.status !== actual.status) {
    problems.push(`exit: py=${expected.status} js=${actual.status}`);
  }
  const expectedOut = normalise(expected.stdout, 'test17_executable');
  const actualOut = normalise(actual.stdout, 'test17.mjs');
  if (expectedOut !== actualOut) {
    problems.push(`stdout:\n    py=${preview(expected.stdout)}\n    js=${preview(actual.stdout)}`);
  }
  const expectedErr = normalise(expected.stderr, 'test17_executable');
  const actualErr = normalise(actual.stderr, 'test17.mjs');
  if (expectedErr !== actualErr) {
    problems.push(`stderr:\n    py=${JSON.stringify(expectedErr)}\n    js=${JSON.stringify(actualErr)}`);
  }

  if (problems.length > 0) {
    failures++;
    console.log(`MISMATCH ${show(argv)}`);
    for (const problem of problems) console.log(`  ${problem}`);
  }
}

console.log(`\n${cases.length - failures}/${cases.length} cases matched`);
process.exit(failures > 0 ? 1 : 0);

// Node.js port of test17.py.
//
// Same CLI (`--a`, required, comma-separated), same 20 results, same print
// order and the same byte-for-byte formatting as Python's `print`.

import { ArgumentParser } from './lib/argparse.mjs';
import { camel2under, under2camel, slugify, unitLen, cardinalize } from './lib/strutils.mjs';
import { FrozenDict } from './lib/dictutils.mjs';
import { PyDict } from './lib/pydict.mjs';
import { pyPrint } from './lib/pyrepr.mjs';
import { pyLen, pyReplace, pySplit, pyUpper } from './lib/pyunicode.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', {
  type: (value) => value,
  required: true,
  help: 'Comma-separated strings',
});
const args = parser.parseArgs();

const strings = pySplit(args.a, ',');

// Group one: string conversion (15 API calls)
const result1 = strings.map((s) => camel2under(s)); // batch camel -> under
pyPrint(result1);
const result2 = strings.map((s) => under2camel(s)); // batch under -> camel
pyPrint(result2);
const result3 = strings.map((s) => slugify(s)); // batch slug creation
pyPrint(result3);
const result4 = camel2under(strings[0]); // convert the first
pyPrint(result4);
const result5 = under2camel(result4); // convert it back
pyPrint(result5);
const result6 = slugify(strings[strings.length - 1]); // slug of the last
pyPrint(result6);
const result7 = unitLen(strings, 'string'); // length description
pyPrint(result7);
const result8 = cardinalize('string', strings.length); // plural form
pyPrint(result8);
const result9 = camel2under(strings.join('')); // convert after joining
pyPrint(result9);
const result10 = slugify(strings.join('_')); // slugify after joining
pyPrint(result10);
const result11 = under2camel(pyReplace(result9, ' ', '_')); // convert after processing
pyPrint(result11);
const result12 = unitLen(strings.slice(0, 3), 'item'); // description of the first 3
pyPrint(result12);
const result13 = cardinalize('item', 1); // singular form
pyPrint(result13);
const result14 = camel2under('TestString'); // fixed string conversion
pyPrint(result14);
const result15 = slugify('Test String!'); // fixed string slugify
pyPrint(result15);

// Group two: dictionary mapping (5 API calls)
const mapping = PyDict.fromZip(strings, result1);
const result16 = new FrozenDict(mapping.items()); // create an immutable dict
pyPrint(result16);
const result17 = mapping.mapEntries((k, v) => [v, k], FrozenDict); // reversed mapping
pyPrint(result17);
const result18 = mapping.mapEntries((k, v) => [k, pyLen(v)], FrozenDict); // length mapping
pyPrint(result18);
const result19 = mapping.mapEntries((k, v) => [pyUpper(k), v], FrozenDict); // upper-cased keys
pyPrint(result19);
const result20 = mapping.mapEntries((k, v) => [k, slugify(v)], FrozenDict); // slugified values
pyPrint(result20);
